            Some("later".to_owned())
        );

        // A blocked queue has no ready task.
        let state = state_with_scope(".", vec![ready_task("blocked", TaskStatus::Blocked, &[])]);
        assert_eq!(resolve_next_ready_task(&state, "."), None);
        // An unknown component has no scope.
