//! Read-only classification of Kvist root artifacts.
//!
//! Phase 1 deliberately does not repair or migrate projects.  This module is
//! the single inspection surface used by `init` and `doctor`, so the decision
//! to refuse a project is based on the same checks shown to its owner.

use std::{
    fmt, fs, io,
    path::{Path, PathBuf},
};

use sha2::{Digest, Sha256};

use crate::{
    KvistError, Result,
    artifacts::{
        ARCHITECTURE_VERSION, CONFIGURATION_VERSION, IMPLEMENTATION_RECORD_HEADING,
        IMPLEMENTATION_RECORD_VERSION, IMPLEMENTATION_RECORD_VERSION_MARKER, ROOT_CONTRACT_VERSION,
        ROOT_IMPLEMENTATION_RECORD_PATH, TODO_QUEUE_VERSION, VISION_VERSION,
    },
    component_documents::{self, DocumentDiagnosticKind, DocumentKind},
    config::{self, DiscoveryLimits},
    discovery::{self, ComponentArtifact},
    filesystem::is_link_like,
    task_queue::{self, StalenessCause, StalenessCauseKind, TaskQueue, TaskQueueError, TaskStatus},
    vcs::{self, VcsInspection},
};

/// Required root artifacts, in stable diagnostic order.
pub const REQUIRED_ROOT_ARTIFACT_PATHS: [&str; 9] = [
    "kvist.toml",
    "VISION.md",
    "ARCHITECTURE.md",
    "ROOT_CONTRACT.md",
    "src/REQUIREMENTS.md",
    "src/CONTRACT.md",
    "src/DESIGN.md",
    "src/TODOS.yaml",
    ROOT_IMPLEMENTATION_RECORD_PATH,
];

/// Root artifact that is machine-local configuration. It must exist and be
/// valid for a current project, but it is not a durable VCS-tracked artifact:
/// local endpoint and toolchain settings must not be forced into version
/// control.
pub const LOCAL_ROOT_ARTIFACT_PATH: &str = "kvist.toml";

/// Maximum supported size for root contract, TODO queue, and implementation records.
pub const MAX_ROOT_TEXT_ARTIFACT_BYTES: u64 = 1024 * 1024;

#[derive(Debug, Clone)]
struct Artifact {
    path: String,
    kind: ArtifactKind,
}

#[derive(Debug, Clone, Copy)]
enum ArtifactKind {
    Configuration,
    Vision,
    Architecture,
    RootContract,
    ComponentDocument(DocumentKind),
    TodoQueue,
    ImplementationRecord,
}

/// The safe Phase 1 state of a project root.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProjectState {
    /// No Kvist root artifact exists.
    Uninitialized,
    /// Every root artifact is a current, valid regular file.
    Current,
    /// Some, but not all, root artifacts exist and those present are valid.
    Partial,
    /// An artifact has an invalid type or content.
    Invalid,
    /// An artifact declares a well-formed version this binary does not support.
    UnsupportedVersion,
}

impl ProjectState {
    /// Stable lowercase name used by `doctor`.
    pub const fn name(self) -> &'static str {
        match self {
            Self::Uninitialized => "uninitialized",
            Self::Current => "current",
            Self::Partial => "partial",
            Self::Invalid => "invalid",
            Self::UnsupportedVersion => "unsupported-version",
        }
    }
}

impl fmt::Display for ProjectState {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.name())
    }
}

/// The inspection result for one required root artifact.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ArtifactStatus {
    /// Artifact path relative to the project root.
    pub path: String,
    /// Human-readable status suitable for `doctor`.
    pub status: String,
    /// Whether this artifact exists at the expected location.
    pub exists: bool,
    class: ArtifactClass,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ArtifactClass {
    Missing,
    Valid,
    Invalid,
    UnsupportedVersion,
}

/// A complete, read-only project inspection.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProjectInspection {
    /// Inspected project directory.
    pub project_dir: PathBuf,
    /// Classification derived from all five required root artifacts.
    pub state: ProjectState,
    /// Per-artifact validation results in stable artifact order.
    pub artifacts: Vec<ArtifactStatus>,
    /// Project-root diagnostic when inspection could not enumerate artifacts.
    pub root_diagnostic: Option<String>,
    /// Read-only durable-artifact tracking inspection.
    pub vcs: VcsInspection,
    /// Action the owner can take without Kvist rewriting project content.
    pub guidance: String,
    /// Configured component root when the root project is current.
    pub component_root: Option<PathBuf>,
    /// Per-component inspection results in lexical path order.
    pub components: Vec<ComponentInspection>,
    /// Discovery failure captured without changing root-artifact classification.
    pub discovery_error: Option<String>,
}

/// The inspected state of one discovered component.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ComponentState {
    /// All component artifacts and workflow evidence are valid and ready.
    Current,
    /// An artifact uses a well-formed version this binary cannot inspect.
    UnsupportedVersion,
    /// An artifact or required parent contract cannot be validated.
    Invalid,
    /// One or more adjacent component artifacts are absent.
    Missing,
    /// The recorded or freshly derived intent-document evidence is stale.
    Stale,
    /// A current queue contains one or more explicitly blocked tasks.
    Blocked,
}

impl ComponentState {
    /// Stable lowercase name used by text and JSON status reports.
    pub const fn name(self) -> &'static str {
        match self {
            Self::Current => "current",
            Self::UnsupportedVersion => "unsupported-version",
            Self::Invalid => "invalid",
            Self::Missing => "missing",
            Self::Stale => "stale",
            Self::Blocked => "blocked",
        }
    }
}

/// The inspected state of one adjacent component artifact.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ComponentArtifactState {
    /// A supported, valid artifact was read and parsed.
    Valid,
    /// No artifact exists at the expected path.
    Missing,
    /// An artifact has an invalid type, encoding, or content.
    Invalid,
    /// An artifact declares a supported-shape but unsupported version.
    UnsupportedVersion,
}

impl ComponentArtifactState {
    /// Stable lowercase name used by text and JSON status reports.
    pub const fn name(self) -> &'static str {
        match self {
            Self::Valid => "valid",
            Self::Missing => "missing",
            Self::Invalid => "invalid",
            Self::UnsupportedVersion => "unsupported-version",
        }
    }
}

/// Status inspection for one adjacent component artifact.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ComponentArtifactInspection {
    /// Filename adjacent to the component directory.
    pub path: &'static str,
    /// Validated artifact state.
    pub state: ComponentArtifactState,
}

/// An attributable recorded or derived intent-document revision mismatch.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RevalidationCause {
    /// The changed local document or immediate-parent contract.
    pub kind: StalenessCauseKind,
    /// Path relative to the component context.
    pub path: String,
    /// Revision recorded when the task queue was reviewed.
    pub expected_revision: String,
    /// Revision observed by this inspection.
    pub observed_revision: String,
}

/// Complete read-only inspection for one discovered component.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ComponentInspection {
    /// Component path relative to the configured component root.
    pub path: PathBuf,
    /// Aggregate state with stable precedence.
    pub state: ComponentState,
    /// Adjacent artifact states in requirements, contract, design, queue, record order.
    pub artifacts: Vec<ComponentArtifactInspection>,
    /// Recorded and freshly derived document evidence explaining stale state.
    pub revalidation_causes: Vec<RevalidationCause>,
}

impl fmt::Display for ProjectInspection {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        writeln!(
            formatter,
            "project: {}\nstate: {}",
            self.project_dir.display(),
            self.state
        )?;
        if let Some(diagnostic) = &self.root_diagnostic {
            writeln!(formatter, "diagnostic: {diagnostic}")?;
        }

        // Group artifacts: project root artifacts vs component artifacts
        let mut root_artifacts = Vec::new();
        let mut component_artifacts: std::collections::BTreeMap<String, Vec<&ArtifactStatus>> =
            std::collections::BTreeMap::new();

        for artifact in &self.artifacts {
            if let Some((comp, _)) = artifact.path.split_once('/') {
                component_artifacts
                    .entry(comp.to_owned())
                    .or_default()
                    .push(artifact);
            } else {
                root_artifacts.push(artifact);
            }
        }

        if !root_artifacts.is_empty() {
            writeln!(formatter, "\n[Project Artifacts]")?;
            for artifact in root_artifacts {
                writeln!(formatter, "  {}: {}", artifact.path, artifact.status)?;
            }
        }

        for (comp_name, comp_arts) in component_artifacts {
            writeln!(formatter, "\n[Component: {comp_name}]")?;
            for artifact in comp_arts {
                writeln!(formatter, "  {}: {}", artifact.path, artifact.status)?;
            }
        }

        writeln!(formatter, "\n[Version Control]")?;
        writeln!(formatter, "  vcs: {}", self.vcs.summary)?;
        if let Some(repository_root) = &self.vcs.repository_root {
            writeln!(formatter, "  vcs repository: {}", repository_root.display())?;
        }

        let mut vcs_root_artifacts = Vec::new();
        let mut vcs_component_artifacts: std::collections::BTreeMap<
            String,
            Vec<&crate::vcs::VcsArtifactStatus>,
        > = std::collections::BTreeMap::new();

        for artifact in &self.vcs.artifacts {
            let path_str = artifact.path.to_string_lossy();
            if let Some((comp, _)) = path_str.split_once('/') {
                vcs_component_artifacts
                    .entry(comp.to_owned())
                    .or_default()
                    .push(artifact);
            } else {
                vcs_root_artifacts.push(artifact);
            }
        }

        if !vcs_root_artifacts.is_empty() {
            writeln!(formatter, "  [Project Artifacts]")?;
            for artifact in vcs_root_artifacts {
                writeln!(
                    formatter,
                    "    vcs {}: {}",
                    artifact.path.display(),
                    artifact.state.description()
                )?;
            }
        }

        for (comp_name, comp_arts) in vcs_component_artifacts {
            writeln!(formatter, "  [Component: {comp_name}]")?;
            for artifact in comp_arts {
                writeln!(
                    formatter,
                    "    vcs {}: {}",
                    artifact.path.display(),
                    artifact.state.description()
                )?;
            }
        }

        if let Some(diagnostic) = &self.vcs.diagnostic {
            writeln!(formatter, "  vcs diagnostic: {diagnostic}")?;
        }
        write!(formatter, "\nguidance: {}", self.guidance)
    }
}

/// Inspects a project without creating, modifying, or following root artifact
/// symbolic links.
pub fn inspect(project_dir: &Path) -> Result<ProjectInspection> {
    let root_exists = match fs::symlink_metadata(project_dir) {
        Ok(metadata) => {
            let file_type = metadata.file_type();
            if is_link_like(&metadata) || !file_type.is_dir() {
                return Ok(invalid_root_inspection(project_dir));
            }
            true
        }
        Err(error) if error.kind() == io::ErrorKind::NotFound => false,
        Err(source) => {
            return Err(KvistError::Io {
                operation: "inspect project directory",
                path: project_dir.to_path_buf(),
                source,
            });
        }
    };

    if !root_exists {
        let artifacts = artifacts_for_project(project_dir);
        return Ok(ProjectInspection {
            project_dir: project_dir.to_path_buf(),
            state: ProjectState::Uninitialized,
            artifacts: artifacts
                .iter()
                .map(|artifact| missing_status(&artifact.path))
                .collect(),
            root_diagnostic: None,
            vcs: VcsInspection::not_checked(
                "root artifacts do not exist yet; initialize and validate the project first",
            ),
            guidance: "run `kvist init` to create the Phase 1 root artifacts".to_owned(),
            component_root: None,
            components: Vec::new(),
            discovery_error: None,
        });
    }

    let artifact_specs = artifacts_for_project(project_dir);
    let artifacts = artifact_specs
        .iter()
        .map(|artifact| inspect_artifact(project_dir, artifact))
        .collect::<Result<Vec<_>>>()?;
    let state = classify(&artifacts);
    let (component_root, components, discovery_error) = inspect_components(project_dir, state)?;
    tracing::debug!(
        project_dir = %project_dir.display(),
        state = state.name(),
        components_count = components.len(),
        "inspected project state"
    );
    Ok(ProjectInspection {
        project_dir: project_dir.to_path_buf(),
        state,
        artifacts,
        root_diagnostic: None,
        vcs: inspect_vcs(project_dir, state),
        guidance: guidance(state).to_owned(),
        component_root,
        components,
        discovery_error,
    })
}

fn artifacts_for_project(project_dir: &Path) -> Vec<Artifact> {
    let component_root = config::load(project_dir)
        .map(|configuration| configuration.component_root)
        .unwrap_or_else(|_| PathBuf::from("src"));

    let mut artifacts = vec![
        Artifact {
            path: "kvist.toml".to_owned(),
            kind: ArtifactKind::Configuration,
        },
        Artifact {
            path: "VISION.md".to_owned(),
            kind: ArtifactKind::Vision,
        },
        Artifact {
            path: "ARCHITECTURE.md".to_owned(),
            kind: ArtifactKind::Architecture,
        },
        Artifact {
            path: "ROOT_CONTRACT.md".to_owned(),
            kind: ArtifactKind::RootContract,
        },
    ];

    if component_root == Path::new(".") {
        if let Ok(discovery) =
            discovery::discover_with_limits(project_dir, DiscoveryLimits::default())
        {
            for component in discovery.components {
                let comp_path = component.relative_path;
                for (doc_kind, art_kind) in [
                    (
                        DocumentKind::Requirements,
                        ArtifactKind::ComponentDocument(DocumentKind::Requirements),
                    ),
                    (
                        DocumentKind::Contract,
                        ArtifactKind::ComponentDocument(DocumentKind::Contract),
                    ),
                    (
                        DocumentKind::Design,
                        ArtifactKind::ComponentDocument(DocumentKind::Design),
                    ),
                ] {
                    artifacts.push(Artifact {
                        path: comp_path
                            .join(doc_kind.filename())
                            .to_string_lossy()
                            .into_owned(),
                        kind: art_kind,
                    });
                }
                artifacts.push(Artifact {
                    path: comp_path
                        .join(ComponentArtifact::TaskQueue.filename())
                        .to_string_lossy()
                        .into_owned(),
                    kind: ArtifactKind::TodoQueue,
                });
                artifacts.push(Artifact {
                    path: comp_path
                        .join(ComponentArtifact::ImplementationRecord.filename())
                        .to_string_lossy()
                        .into_owned(),
                    kind: ArtifactKind::ImplementationRecord,
                });
            }
        }
    } else {
        let component_path =
            |filename: &str| component_root.join(filename).to_string_lossy().into_owned();

        artifacts.extend([
            Artifact {
                path: component_path(DocumentKind::Requirements.filename()),
                kind: ArtifactKind::ComponentDocument(DocumentKind::Requirements),
            },
            Artifact {
                path: component_path(DocumentKind::Contract.filename()),
                kind: ArtifactKind::ComponentDocument(DocumentKind::Contract),
            },
            Artifact {
                path: component_path(DocumentKind::Design.filename()),
                kind: ArtifactKind::ComponentDocument(DocumentKind::Design),
            },
            Artifact {
                path: component_path(ComponentArtifact::TaskQueue.filename()),
                kind: ArtifactKind::TodoQueue,
            },
            Artifact {
                path: component_path(ComponentArtifact::ImplementationRecord.filename()),
                kind: ArtifactKind::ImplementationRecord,
            },
        ]);
    }

    artifacts
}

fn invalid_root_inspection(project_dir: &Path) -> ProjectInspection {
    ProjectInspection {
        project_dir: project_dir.to_path_buf(),
        state: ProjectState::Invalid,
        artifacts: Vec::new(),
        root_diagnostic: Some(
            "project path must be a real directory, not a file or link-like path".to_owned(),
        ),
        vcs: VcsInspection::not_checked(
            "project root is not a real directory, so durable artifact paths cannot be inspected",
        ),
        guidance: guidance(ProjectState::Invalid).to_owned(),
        component_root: None,
        components: Vec::new(),
        discovery_error: None,
    }
}

fn inspect_components(
    project_dir: &Path,
    project_state: ProjectState,
) -> Result<(Option<PathBuf>, Vec<ComponentInspection>, Option<String>)> {
    if project_state != ProjectState::Current {
        return Ok((None, Vec::new(), None));
    }

    let config = match config::load(project_dir) {
        Ok(config) => config,
        Err(error) => return Ok((None, Vec::new(), Some(error.to_string()))),
    };
    let component_root = config.component_root.clone();
    let discovery =
        match discovery::discover_with_limits(&project_dir.join(&component_root), config.discovery)
        {
            Ok(discovery) => discovery,
            Err(error) => return Ok((Some(component_root), Vec::new(), Some(error.to_string()))),
        };

    let components = discovery
        .components
        .iter()
        .map(|component| inspect_component(&project_dir.join(&component_root), component))
        .collect::<Result<Vec<_>>>()?;
    Ok((Some(component_root), components, None))
}

fn inspect_component(
    component_root: &Path,
    component: &discovery::Component,
) -> Result<ComponentInspection> {
    let component_dir = component_root.join(&component.relative_path);
    let requirements_path = component_dir.join(ComponentArtifact::Requirements.filename());
    let contract_path = component_dir.join(ComponentArtifact::Contract.filename());
    let design_path = component_dir.join(ComponentArtifact::Design.filename());
    let queue_path = component_dir.join(ComponentArtifact::TaskQueue.filename());
    let implementation_record_path =
        component_dir.join(ComponentArtifact::ImplementationRecord.filename());

    let (requirements_state, requirements_contents) =
        inspect_component_document(DocumentKind::Requirements, &requirements_path)?;
    let (contract_state, contract_contents) =
        inspect_component_document(DocumentKind::Contract, &contract_path)?;
    let (design_state, design_contents) =
        inspect_component_document(DocumentKind::Design, &design_path)?;
    let (queue_state, queue) = inspect_component_queue(&queue_path)?;
    let implementation_record_state =
        inspect_component_implementation_record(&implementation_record_path)?;
    let artifacts = vec![
        ComponentArtifactInspection {
            path: ComponentArtifact::Requirements.filename(),
            state: requirements_state,
        },
        ComponentArtifactInspection {
            path: ComponentArtifact::Contract.filename(),
            state: contract_state,
        },
        ComponentArtifactInspection {
            path: ComponentArtifact::Design.filename(),
            state: design_state,
        },
        ComponentArtifactInspection {
            path: ComponentArtifact::TaskQueue.filename(),
            state: queue_state,
        },
        ComponentArtifactInspection {
            path: ComponentArtifact::ImplementationRecord.filename(),
            state: implementation_record_state,
        },
    ];

    let mut revalidation_causes = Vec::new();
    let mut context_is_invalid = false;
    let mut queue_is_stale = false;
    let mut has_blocked_task = false;
    if let Some(queue) = queue {
        queue_is_stale = matches!(
            queue.component.revalidation.state,
            task_queue::RevalidationState::Stale
        );
        revalidation_causes.extend(
            queue
                .component
                .revalidation
                .causes
                .iter()
                .map(revalidation_cause),
        );

        if let Some(contents) = requirements_contents.as_deref() {
            add_revision_cause(
                &mut revalidation_causes,
                StalenessCauseKind::ComponentRequirementsRevisionChanged,
                ComponentArtifact::Requirements.filename(),
                &queue.component.requirements_revision,
                sha256_revision(contents),
            );
        }
        if let Some(contents) = contract_contents.as_deref() {
            add_revision_cause(
                &mut revalidation_causes,
                StalenessCauseKind::ComponentContractRevisionChanged,
                ComponentArtifact::Contract.filename(),
                &queue.component.contract_revision,
                sha256_revision(contents),
            );
        }
        if let Some(contents) = design_contents.as_deref() {
            add_revision_cause(
                &mut revalidation_causes,
                StalenessCauseKind::ComponentDesignRevisionChanged,
                ComponentArtifact::Design.filename(),
                &queue.component.design_revision,
                sha256_revision(contents),
            );
        }

        let parent_info =
            discovery::find_parent_component(component_root, &component.relative_path)?;
        match (&queue.component.parent_contract, parent_info) {
            (None, None) => {}
            (Some(_), None) | (None, Some(_)) => context_is_invalid = true,
            (Some(parent), Some((parent_component_dir, parent_relative_path))) => {
                let parent_contract =
                    parent_component_dir.join(ComponentArtifact::Contract.filename());
                let (state, contents) =
                    inspect_component_document(DocumentKind::Contract, &parent_contract)?;
                if state != ComponentArtifactState::Valid {
                    context_is_invalid = true;
                } else if let Some(contents) = contents {
                    let relative_parent_path = relative_parent_contract_path(
                        &component.relative_path,
                        &parent_relative_path,
                    );
                    if parent.path != relative_parent_path {
                        context_is_invalid = true;
                    }
                    add_revision_cause(
                        &mut revalidation_causes,
                        StalenessCauseKind::ParentContractRevisionChanged,
                        &relative_parent_path,
                        &parent.revision,
                        sha256_revision(&contents),
                    );
                }
            }
        }
        has_blocked_task = queue
            .tasks
            .iter()
            .any(|task| task.status == TaskStatus::Blocked);
    }

    let state = if artifacts
        .iter()
        .any(|artifact| artifact.state == ComponentArtifactState::UnsupportedVersion)
    {
        ComponentState::UnsupportedVersion
    } else if artifacts
        .iter()
        .any(|artifact| artifact.state == ComponentArtifactState::Invalid)
        || context_is_invalid
    {
        ComponentState::Invalid
    } else if artifacts
        .iter()
        .any(|artifact| artifact.state == ComponentArtifactState::Missing)
    {
        ComponentState::Missing
    } else if queue_is_stale || !revalidation_causes.is_empty() {
        ComponentState::Stale
    } else if has_blocked_task {
        ComponentState::Blocked
    } else {
        ComponentState::Current
    };

    Ok(ComponentInspection {
        path: if is_component_root(&component.relative_path) {
            PathBuf::from(".")
        } else {
            component.relative_path.clone()
        },
        state,
        artifacts,
        revalidation_causes,
    })
}

fn is_component_root(path: &Path) -> bool {
    path.as_os_str().is_empty() || path == Path::new(".")
}

pub(crate) fn relative_parent_contract_path(
    relative_path: &Path,
    parent_relative_path: &Path,
) -> String {
    if parent_relative_path.as_os_str().is_empty() || parent_relative_path == Path::new(".") {
        let depth = relative_path.components().count();
        let mut path = String::new();
        for _ in 0..depth {
            path.push_str("../");
        }
        path.push_str("CONTRACT.md");
        path
    } else {
        let child_depth = relative_path.components().count();
        let parent_depth = parent_relative_path.components().count();
        let mut path = String::new();
        for _ in 0..(child_depth - parent_depth) {
            path.push_str("../");
        }
        path.push_str("CONTRACT.md");
        path
    }
}

fn revalidation_cause(cause: &StalenessCause) -> RevalidationCause {
    RevalidationCause {
        kind: cause.kind,
        path: cause.path.clone(),
        expected_revision: cause.expected_revision.clone(),
        observed_revision: cause.observed_revision.clone(),
    }
}

fn add_revision_cause(
    causes: &mut Vec<RevalidationCause>,
    kind: StalenessCauseKind,
    path: &str,
    expected_revision: &str,
    observed_revision: String,
) {
    if expected_revision == observed_revision {
        return;
    }
    let cause = RevalidationCause {
        kind,
        path: path.to_owned(),
        expected_revision: expected_revision.to_owned(),
        observed_revision,
    };
    if !causes.contains(&cause) {
        causes.push(cause);
    }
}

fn sha256_revision(contents: &str) -> String {
    format!(
        "sha256:{}",
        hex::encode(Sha256::digest(contents.as_bytes()))
    )
}

fn inspect_component_document(
    kind: DocumentKind,
    path: &Path,
) -> Result<(ComponentArtifactState, Option<String>)> {
    let Some(contents) = read_component_text_artifact(path)? else {
        return Ok((component_path_state(path)?, None));
    };
    let validation = component_documents::validate(kind, &contents);
    if validation.is_valid() {
        Ok((ComponentArtifactState::Valid, Some(contents)))
    } else if validation.diagnostics.iter().any(|diagnostic| {
        matches!(
            diagnostic.kind,
            DocumentDiagnosticKind::UnsupportedTemplateVersion { .. }
        )
    }) {
        Ok((ComponentArtifactState::UnsupportedVersion, None))
    } else {
        Ok((ComponentArtifactState::Invalid, None))
    }
}

fn inspect_component_queue(path: &Path) -> Result<(ComponentArtifactState, Option<TaskQueue>)> {
    let Some(contents) = read_component_text_artifact(path)? else {
        return Ok((component_path_state(path)?, None));
    };
    match task_queue::parse(&contents) {
        Ok(queue) => Ok((ComponentArtifactState::Valid, Some(queue))),
        Err(TaskQueueError::UnsupportedVersion { .. }) => {
            Ok((ComponentArtifactState::UnsupportedVersion, None))
        }
        Err(_) => Ok((ComponentArtifactState::Invalid, None)),
    }
}

fn inspect_component_implementation_record(path: &Path) -> Result<ComponentArtifactState> {
    let Some(contents) = read_component_text_artifact(path)? else {
        return component_path_state(path);
    };
    Ok(markdown_component_state(
        &contents,
        IMPLEMENTATION_RECORD_VERSION_MARKER,
        IMPLEMENTATION_RECORD_VERSION,
        IMPLEMENTATION_RECORD_HEADING,
    ))
}

fn read_component_text_artifact(path: &Path) -> Result<Option<String>> {
    let metadata = match fs::symlink_metadata(path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(None),
        Err(source) => {
            return Err(KvistError::Io {
                operation: "inspect component artifact",
                path: path.to_path_buf(),
                source,
            });
        }
    };
    if is_link_like(&metadata) || !metadata.file_type().is_file() {
        return Ok(None);
    }
    if metadata.len() > MAX_ROOT_TEXT_ARTIFACT_BYTES {
        return Ok(None);
    }
    match fs::read_to_string(path) {
        Ok(contents) => Ok(Some(contents)),
        Err(source) if source.kind() == io::ErrorKind::InvalidData => Ok(None),
        Err(source) => Err(KvistError::Io {
            operation: "read component artifact",
            path: path.to_path_buf(),
            source,
        }),
    }
}

fn component_path_state(path: &Path) -> Result<ComponentArtifactState> {
    let metadata = match fs::symlink_metadata(path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            return Ok(ComponentArtifactState::Missing);
        }
        Err(source) => {
            return Err(KvistError::Io {
                operation: "inspect component artifact",
                path: path.to_path_buf(),
                source,
            });
        }
    };
    if is_link_like(&metadata)
        || !metadata.file_type().is_file()
        || metadata.len() > MAX_ROOT_TEXT_ARTIFACT_BYTES
    {
        return Ok(ComponentArtifactState::Invalid);
    }
    match fs::read_to_string(path) {
        Ok(_) => Ok(ComponentArtifactState::Invalid),
        Err(source) if source.kind() == io::ErrorKind::InvalidData => {
            Ok(ComponentArtifactState::Invalid)
        }
        Err(source) => Err(KvistError::Io {
            operation: "read component artifact",
            path: path.to_path_buf(),
            source,
        }),
    }
}

fn markdown_component_state(
    contents: &str,
    marker_name: &str,
    supported_version: u32,
    required_heading: &str,
) -> ComponentArtifactState {
    let expected_prefix = format!("<!-- {marker_name}: ");
    let first_line = contents.lines().next().unwrap_or_default();
    let Some(version_text) = first_line
        .strip_prefix(&expected_prefix)
        .and_then(|value| value.strip_suffix(" -->"))
    else {
        return ComponentArtifactState::Invalid;
    };
    let Ok(version) = version_text.parse::<u32>() else {
        return ComponentArtifactState::Invalid;
    };
    if version == 0 {
        return ComponentArtifactState::Invalid;
    }
    if version != supported_version {
        return ComponentArtifactState::UnsupportedVersion;
    }
    if !contents.lines().any(|line| line == required_heading) {
        return ComponentArtifactState::Invalid;
    }
    ComponentArtifactState::Valid
}

fn inspect_vcs(project_dir: &Path, state: ProjectState) -> VcsInspection {
    if state != ProjectState::Current {
        return VcsInspection::not_checked(
            "root artifact state is not current; repair it before checking durable-artifact tracking",
        );
    }

    let config = match config::load(project_dir) {
        Ok(config) => config,
        Err(error) => {
            return VcsInspection::not_checked(format!(
                "cannot load current project configuration for VCS inspection: {error}"
            ));
        }
    };
    let discovery = match discovery::discover_with_limits(
        &project_dir.join(&config.component_root),
        config.discovery,
    ) {
        Ok(discovery) => discovery,
        Err(error) => {
            return VcsInspection::not_checked(format!(
                "cannot discover component artifacts for VCS inspection: {error}"
            ));
        }
    };

    let mut required_paths = REQUIRED_ROOT_ARTIFACT_PATHS[..4]
        .iter()
        .filter(|path| **path != LOCAL_ROOT_ARTIFACT_PATH)
        .map(PathBuf::from)
        .collect::<Vec<_>>();
    for component in discovery.components {
        let component_dir = if component.relative_path == Path::new(".") {
            config.component_root.clone()
        } else if config.component_root == Path::new(".") {
            component.relative_path.clone()
        } else {
            config.component_root.join(component.relative_path)
        };
        for artifact in [
            ComponentArtifact::Requirements,
            ComponentArtifact::Contract,
            ComponentArtifact::Design,
            ComponentArtifact::TaskQueue,
            ComponentArtifact::ImplementationRecord,
        ] {
            required_paths.push(component_dir.join(artifact.filename()));
        }
    }

    vcs::inspect(project_dir, config.vcs, required_paths)
}

fn inspect_artifact(project_dir: &Path, artifact: &Artifact) -> Result<ArtifactStatus> {
    let path = project_dir.join(&artifact.path);
    if let Some(parent_problem) = parent_problem(project_dir, &artifact.path)? {
        return Ok(ArtifactStatus {
            path: artifact.path.clone(),
            status: parent_problem,
            exists: false,
            class: ArtifactClass::Invalid,
        });
    }

    let metadata = match fs::symlink_metadata(&path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            return Ok(missing_status(&artifact.path));
        }
        Err(source) => {
            return Err(KvistError::Io {
                operation: "inspect root artifact",
                path,
                source,
            });
        }
    };
    let file_type = metadata.file_type();
    if is_link_like(&metadata) {
        return Ok(invalid_status(&artifact.path, "invalid (link-like path)"));
    }
    if !file_type.is_file() {
        return Ok(invalid_status(
            &artifact.path,
            "invalid (must be a regular file)",
        ));
    }

    validate_artifact(project_dir, artifact)
}

fn parent_problem(project_dir: &Path, relative_path: &str) -> Result<Option<String>> {
    let Some(parent) = Path::new(relative_path).parent() else {
        return Ok(None);
    };
    if parent.as_os_str().is_empty() {
        return Ok(None);
    }
    let path = project_dir.join(parent);
    match fs::symlink_metadata(&path) {
        Ok(metadata) if is_link_like(&metadata) => Ok(Some(format!(
            "invalid (parent `{}` is link-like)",
            parent.display()
        ))),
        Ok(metadata) if !metadata.file_type().is_dir() => Ok(Some(format!(
            "invalid (parent `{}` is not a directory)",
            parent.display()
        ))),
        Ok(_) => Ok(None),
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(None),
        Err(source) => Err(KvistError::Io {
            operation: "inspect root artifact parent",
            path,
            source,
        }),
    }
}

fn validate_artifact(project_dir: &Path, artifact: &Artifact) -> Result<ArtifactStatus> {
    let path = project_dir.join(&artifact.path);
    match artifact.kind {
        ArtifactKind::Configuration => match config::load(project_dir) {
            Ok(_) => Ok(valid_status(
                &artifact.path,
                format!("valid (configuration version {CONFIGURATION_VERSION})"),
            )),
            Err(KvistError::UnsupportedProjectConfigurationVersion { version, .. }) => {
                Ok(unsupported_status(
                    &artifact.path,
                    format!(
                        "unsupported version {version} (supported configuration version {CONFIGURATION_VERSION})"
                    ),
                ))
            }
            Err(error) => Ok(invalid_status(&artifact.path, format!("invalid ({error})"))),
        },
        ArtifactKind::Vision => validate_markdown_version(
            &artifact.path,
            &path,
            "kvist-vision-version",
            VISION_VERSION,
            "# Project Vision",
        ),
        ArtifactKind::Architecture => validate_markdown_version(
            &artifact.path,
            &path,
            "kvist-architecture-version",
            ARCHITECTURE_VERSION,
            "# Project Architecture",
        ),
        ArtifactKind::RootContract => validate_markdown_version(
            &artifact.path,
            &path,
            "kvist-root-contract-version",
            ROOT_CONTRACT_VERSION,
            "# Kvist Root Contract",
        ),
        ArtifactKind::ComponentDocument(kind) => {
            let validation = match component_documents::validate_file(kind, &path) {
                Ok(validation) => validation,
                Err(KvistError::ComponentDocumentTooLarge { .. }) => {
                    return Ok(invalid_status(
                        &artifact.path,
                        format!(
                            "invalid (exceeds the {MAX_ROOT_TEXT_ARTIFACT_BYTES}-byte root artifact limit)"
                        ),
                    ));
                }
                Err(
                    KvistError::ComponentDocumentIsSymlink { .. }
                    | KvistError::ComponentDocumentNotFile { .. },
                ) => {
                    return Ok(invalid_status(
                        &artifact.path,
                        "invalid (must be a regular non-symbolic-link file)",
                    ));
                }
                Err(KvistError::Io { source, .. })
                    if source.kind() == io::ErrorKind::InvalidData =>
                {
                    return Ok(invalid_status(
                        &artifact.path,
                        "invalid (must be valid UTF-8)",
                    ));
                }
                Err(error) => return Err(error),
            };
            if validation.is_valid() {
                Ok(valid_status(
                    &artifact.path,
                    format!("valid ({} version {})", kind.filename(), kind.version()),
                ))
            } else if let Some(DocumentDiagnosticKind::UnsupportedTemplateVersion {
                found, ..
            }) =
                validation
                    .diagnostics
                    .iter()
                    .find_map(|diagnostic| match &diagnostic.kind {
                        kind @ DocumentDiagnosticKind::UnsupportedTemplateVersion { .. } => {
                            Some(kind)
                        }
                        _ => None,
                    })
            {
                Ok(unsupported_status(
                    &artifact.path,
                    format!(
                        "unsupported version {found} (supported {} version {})",
                        kind.filename(),
                        kind.version()
                    ),
                ))
            } else {
                Ok(invalid_status(
                    &artifact.path,
                    format!(
                        "invalid ({})",
                        component_documents::format_diagnostics(&validation.diagnostics)
                    ),
                ))
            }
        }
        ArtifactKind::TodoQueue => validate_todo_queue(&artifact.path, &path),
        ArtifactKind::ImplementationRecord => validate_markdown_version(
            &artifact.path,
            &path,
            IMPLEMENTATION_RECORD_VERSION_MARKER,
            IMPLEMENTATION_RECORD_VERSION,
            IMPLEMENTATION_RECORD_HEADING,
        ),
    }
}

fn validate_markdown_version(
    relative_path: &str,
    path: &Path,
    marker_name: &str,
    supported_version: u32,
    required_heading: &str,
) -> Result<ArtifactStatus> {
    let contents = match read_root_text_artifact(relative_path, path)? {
        Ok(contents) => contents,
        Err(status) => return Ok(status),
    };
    let expected_prefix = format!("<!-- {marker_name}: ");
    let first_line = contents.lines().next().unwrap_or_default();
    let Some(version_text) = first_line
        .strip_prefix(&expected_prefix)
        .and_then(|value| value.strip_suffix(" -->"))
    else {
        return Ok(invalid_status(
            relative_path,
            format!("invalid (line 1 must be `{expected_prefix}<positive integer> -->`)"),
        ));
    };
    let Ok(version) = version_text.parse::<u32>() else {
        return Ok(invalid_status(
            relative_path,
            "invalid (version must be a positive integer)",
        ));
    };
    if version == 0 {
        return Ok(invalid_status(
            relative_path,
            "invalid (version must be a positive integer)",
        ));
    }
    if version != supported_version {
        return Ok(unsupported_status(
            relative_path,
            format!("unsupported version {version} (supported version {supported_version})"),
        ));
    }
    if !contents.lines().any(|line| line == required_heading) {
        return Ok(invalid_status(
            relative_path,
            format!("invalid (missing required heading `{required_heading}`)"),
        ));
    }
    Ok(valid_status(
        relative_path,
        format!("valid (version {supported_version})"),
    ))
}

fn validate_todo_queue(relative_path: &str, path: &Path) -> Result<ArtifactStatus> {
    let contents = match read_root_text_artifact(relative_path, path)? {
        Ok(contents) => contents,
        Err(status) => return Ok(status),
    };
    match task_queue::parse(&contents) {
        Ok(_) => Ok(valid_status(
            relative_path,
            format!("valid (TODO queue version {TODO_QUEUE_VERSION})"),
        )),
        Err(TaskQueueError::UnsupportedVersion { found, .. }) => Ok(unsupported_status(
            relative_path,
            format!(
                "unsupported version {found} (supported TODO queue version {TODO_QUEUE_VERSION})"
            ),
        )),
        Err(error) => Ok(invalid_status(relative_path, format!("invalid ({error})"))),
    }
}

fn read_root_text_artifact(
    relative_path: &str,
    path: &Path,
) -> Result<std::result::Result<String, ArtifactStatus>> {
    let metadata = fs::metadata(path).map_err(|source| KvistError::Io {
        operation: "inspect root artifact",
        path: path.to_path_buf(),
        source,
    })?;
    if metadata.len() > MAX_ROOT_TEXT_ARTIFACT_BYTES {
        return Ok(Err(invalid_status(
            relative_path,
            format!(
                "invalid (exceeds the {MAX_ROOT_TEXT_ARTIFACT_BYTES}-byte root artifact limit)"
            ),
        )));
    }

    match fs::read_to_string(path) {
        Ok(contents) => Ok(Ok(contents)),
        Err(source) if source.kind() == io::ErrorKind::InvalidData => Ok(Err(invalid_status(
            relative_path,
            "invalid (must be valid UTF-8)",
        ))),
        Err(source) => Err(KvistError::Io {
            operation: "read root artifact",
            path: path.to_path_buf(),
            source,
        }),
    }
}

fn classify(artifacts: &[ArtifactStatus]) -> ProjectState {
    if artifacts
        .iter()
        .any(|artifact| artifact.class == ArtifactClass::UnsupportedVersion)
    {
        ProjectState::UnsupportedVersion
    } else if artifacts
        .iter()
        .any(|artifact| artifact.class == ArtifactClass::Invalid)
    {
        ProjectState::Invalid
    } else if artifacts
        .iter()
        .all(|artifact| artifact.class == ArtifactClass::Missing)
    {
        ProjectState::Uninitialized
    } else if artifacts
        .iter()
        .all(|artifact| artifact.class == ArtifactClass::Valid)
    {
        ProjectState::Current
    } else {
        ProjectState::Partial
    }
}

fn guidance(state: ProjectState) -> &'static str {
    match state {
        ProjectState::Uninitialized => "run `kvist init` to create the Phase 1 root artifacts",
        ProjectState::Current => "project is ready for Phase 1 read-only commands",
        ProjectState::Partial | ProjectState::Invalid | ProjectState::UnsupportedVersion => {
            "Phase 1 never repairs or migrates artifacts automatically; preserve user content, inspect these diagnostics, and repair or migrate explicitly. A future explicit migration/repair command must define every rewrite."
        }
    }
}

fn missing_status(path: &str) -> ArtifactStatus {
    ArtifactStatus {
        path: path.to_owned(),
        status: "missing".to_owned(),
        exists: false,
        class: ArtifactClass::Missing,
    }
}

fn valid_status(path: &str, status: String) -> ArtifactStatus {
    ArtifactStatus {
        path: path.to_owned(),
        status,
        exists: true,
        class: ArtifactClass::Valid,
    }
}

fn invalid_status(path: &str, status: impl Into<String>) -> ArtifactStatus {
    ArtifactStatus {
        path: path.to_owned(),
        status: status.into(),
        exists: true,
        class: ArtifactClass::Invalid,
    }
}

fn unsupported_status(path: &str, status: String) -> ArtifactStatus {
    ArtifactStatus {
        path: path.to_owned(),
        status,
        exists: true,
        class: ArtifactClass::UnsupportedVersion,
    }
}

#[cfg(test)]
mod tests {
    use std::fs;

    use tempfile::TempDir;

    use crate::{artifacts::root_artifacts, init::initialize};

    use super::*;

    #[test]
    fn independent_version_domains_are_declared() {
        assert_eq!(CONFIGURATION_VERSION, 1);
        assert_eq!(VISION_VERSION, 1);
        assert_eq!(ARCHITECTURE_VERSION, 1);
        assert_eq!(ROOT_CONTRACT_VERSION, 1);
        assert_eq!(component_documents::REQUIREMENTS_VERSION, 1);
        assert_eq!(component_documents::CONTRACT_VERSION, 1);
        assert_eq!(component_documents::DESIGN_VERSION, 1);
        assert_eq!(TODO_QUEUE_VERSION, 1);
        assert_eq!(IMPLEMENTATION_RECORD_VERSION, 1);
    }

    #[test]
    fn classifies_every_project_state() {
        let uninitialized = TempDir::new().expect("workspace");
        assert_eq!(
            inspect(uninitialized.path()).expect("inspect").state,
            ProjectState::Uninitialized
        );

        let current = TempDir::new().expect("workspace");
        initialize(current.path()).expect("initialize");
        assert_eq!(
            inspect(current.path()).expect("inspect").state,
            ProjectState::Current
        );

        let partial = TempDir::new().expect("workspace");
        fs::write(
            partial.path().join("kvist.toml"),
            root_artifacts()[0].contents,
        )
        .expect("write");
        assert_eq!(
            inspect(partial.path()).expect("inspect").state,
            ProjectState::Partial
        );

        let invalid = TempDir::new().expect("workspace");
        initialize(invalid.path()).expect("initialize");
        fs::write(invalid.path().join("ROOT_CONTRACT.md"), "not a contract").expect("write");
        assert_eq!(
            inspect(invalid.path()).expect("inspect").state,
            ProjectState::Invalid
        );

        let unsupported = TempDir::new().expect("workspace");
        initialize(unsupported.path()).expect("initialize");
        fs::write(
            unsupported.path().join("src/TODOS.yaml"),
            "schema_version: 99\ntasks: []\n",
        )
        .expect("write");
        assert_eq!(
            inspect(unsupported.path()).expect("inspect").state,
            ProjectState::UnsupportedVersion
        );
    }
}

//! Deterministic, read-only project status rendering.

use std::{fs, path::Path};

use clap::ValueEnum;

use crate::{
    project_state::{ComponentInspection, ComponentState, ProjectInspection, RevalidationCause},
    task_queue::StalenessCauseKind,
};

/// Presentation format for the versioned status report.
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum StatusFormat {
    /// Stable human-readable text intended for terminals and simple scripts.
    Text,
    /// Stable compact JSON intended for structured automation.
    Json,
    /// High-level human-friendly project overview with progress and next tasks.
    Overview,
}

/// Renders a completed project inspection without performing any filesystem I/O.
pub fn render(
    inspection: &ProjectInspection,
    format: StatusFormat,
    only_documents: bool,
    only_impls: bool,
    unfinished: bool,
) -> String {
    match format {
        StatusFormat::Text => render_text(inspection, only_documents, only_impls, unfinished),
        StatusFormat::Json => render_json(inspection, only_documents, only_impls, unfinished),
        StatusFormat::Overview => render_overview(inspection),
    }
}

fn render_text(
    inspection: &ProjectInspection,
    only_documents: bool,
    only_impls: bool,
    unfinished: bool,
) -> String {
    let mut output = format!(
        "status-format-version: 1\nproject: {}\nproject-state: {}",
        escape_text(&inspection.project_dir.to_string_lossy()),
        inspection.state.name()
    );
    match &inspection.component_root {
        Some(component_root) => {
            output.push_str("\ncomponent-root: ");
            output.push_str(&escape_text(&component_root.to_string_lossy()));
        }
        None => output.push_str("\ncomponent-root: unavailable"),
    }
    if let Some(error) = &inspection.discovery_error {
        output.push_str("\ndiscovery-error: ");
        output.push_str(&escape_text(error));
    }
    for component in &inspection.components {
        if unfinished && component.state == ComponentState::Current {
            continue;
        }
        output.push_str("\ncomponent: ");
        output.push_str(&escape_text(&component.path.to_string_lossy()));
        output.push_str(" state: ");
        output.push_str(component.state.name());
        for artifact in &component.artifacts {
            if only_documents
                && !matches!(
                    artifact.path,
                    "REQUIREMENTS.md" | "CONTRACT.md" | "DESIGN.md"
                )
            {
                continue;
            }
            if only_impls && artifact.path != "IMPL.md" {
                continue;
            }
            output.push_str("\n  ");
            output.push_str(artifact.path);
            output.push_str(": ");
            output.push_str(artifact.state.name());
        }
        if !only_impls {
            if component.revalidation_causes.is_empty() {
                output.push_str("\n  revalidation-causes: []");
            } else {
                for cause in &component.revalidation_causes {
                    output.push_str("\n  cause: ");
                    output.push_str(staleness_kind_name(cause.kind));
                    output.push(' ');
                    output.push_str(&escape_text(&cause.path));
                    output.push_str(" expected ");
                    output.push_str(&escape_text(&cause.expected_revision));
                    output.push_str(" observed ");
                    output.push_str(&escape_text(&cause.observed_revision));
                }
            }
        }
        if component.state == ComponentState::Stale {
            output.push_str(&format!(
                "\n  Next Step: Component intent documents have changed. Run 'kvist component accept {}' after review to record their revisions.",
                escape_text(&component.path.to_string_lossy())
            ));
        } else if component.state == ComponentState::Blocked {
            output.push_str(&format!(
                "\n  Next Step: Component tasks are blocked or need manual intervention. Resolve the blocked tasks or manual gates in {}/TODOS.yaml.",
                escape_text(&component.path.to_string_lossy())
            ));
        } else if component.state == ComponentState::Invalid {
            output.push_str(&format!(
                "\n  Next Step: The component contains invalid or malformed artifacts. Run 'kvist component validate {}' and check the reported Markdown or YAML document.",
                escape_text(&component.path.to_string_lossy())
            ));
        } else if component.state == ComponentState::Missing {
            output.push_str(&format!(
                "\n  Next Step: The component is missing required adjacent Kvist artifacts. Run 'kvist component new {}' to create its intent-document templates.",
                escape_text(&component.path.to_string_lossy())
            ));
        }
    }
    output
}

fn render_json(
    inspection: &ProjectInspection,
    only_documents: bool,
    only_impls: bool,
    unfinished: bool,
) -> String {
    let mut output = String::from("{\"format_version\":1,\"project_path\":");
    json_string(&mut output, &inspection.project_dir.to_string_lossy());
    output.push_str(",\"project_state\":");
    json_string(&mut output, inspection.state.name());
    output.push_str(",\"component_root\":");
    match &inspection.component_root {
        Some(component_root) => json_string(&mut output, &component_root.to_string_lossy()),
        None => output.push_str("null"),
    }
    output.push_str(",\"components\":[");
    let mut rendered_any = false;
    for component in &inspection.components {
        if unfinished && component.state == ComponentState::Current {
            continue;
        }
        if rendered_any {
            output.push(',');
        }
        append_component_json(&mut output, component, only_documents, only_impls);
        rendered_any = true;
    }
    output.push_str("],\"discovery_error\":");
    match &inspection.discovery_error {
        Some(error) => json_string(&mut output, error),
        None => output.push_str("null"),
    }
    output.push('}');
    output
}

fn append_component_json(
    output: &mut String,
    component: &ComponentInspection,
    only_documents: bool,
    only_impls: bool,
) {
    output.push_str("{\"path\":");
    json_string(output, &component.path.to_string_lossy());
    output.push_str(",\"state\":");
    json_string(output, component.state.name());
    output.push_str(",\"artifacts\":[");
    let mut rendered_any_artifact = false;
    for artifact in &component.artifacts {
        if only_documents
            && !matches!(
                artifact.path,
                "REQUIREMENTS.md" | "CONTRACT.md" | "DESIGN.md"
            )
        {
            continue;
        }
        if only_impls && artifact.path != "IMPL.md" {
            continue;
        }
        if rendered_any_artifact {
            output.push(',');
        }
        output.push_str("{\"path\":");
        json_string(output, artifact.path);
        output.push_str(",\"state\":");
        json_string(output, artifact.state.name());
        output.push('}');
        rendered_any_artifact = true;
    }
    output.push_str("],\"revalidation_causes\":[");
    if !only_impls {
        for (index, cause) in component.revalidation_causes.iter().enumerate() {
            if index > 0 {
                output.push(',');
            }
            append_cause_json(output, cause);
        }
    }
    output.push_str("]}");
}

fn append_cause_json(output: &mut String, cause: &RevalidationCause) {
    output.push_str("{\"kind\":");
    json_string(output, staleness_kind_name(cause.kind));
    output.push_str(",\"path\":");
    json_string(output, &cause.path);
    output.push_str(",\"expected_revision\":");
    json_string(output, &cause.expected_revision);
    output.push_str(",\"observed_revision\":");
    json_string(output, &cause.observed_revision);
    output.push('}');
}

fn json_string(output: &mut String, value: &str) {
    output.push('"');
    for character in value.chars() {
        match character {
            '"' => output.push_str("\\\""),
            '\\' => output.push_str("\\\\"),
            '\n' => output.push_str("\\n"),
            '\r' => output.push_str("\\r"),
            '\t' => output.push_str("\\t"),
            '\u{08}' => output.push_str("\\b"),
            '\u{0c}' => output.push_str("\\f"),
            '\0'..='\u{1f}' => {
                use std::fmt::Write;

                let _ = write!(output, "\\u{:04x}", character as u32);
            }
            _ => output.push(character),
        }
    }
    output.push('"');
}

fn escape_text(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '\\' => escaped.push_str("\\\\"),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            '\0'..='\u{1f}' | '\u{7f}' => {
                use std::fmt::Write;

                let _ = write!(escaped, "\\u{:04x}", character as u32);
            }
            _ => escaped.push(character),
        }
    }
    escaped
}

fn staleness_kind_name(kind: StalenessCauseKind) -> &'static str {
    match kind {
        StalenessCauseKind::ComponentRequirementsRevisionChanged => {
            "component-requirements-revision-changed"
        }
        StalenessCauseKind::ComponentContractRevisionChanged => {
            "component-contract-revision-changed"
        }
        StalenessCauseKind::ComponentDesignRevisionChanged => "component-design-revision-changed",
        StalenessCauseKind::ParentContractRevisionChanged => "parent-contract-revision-changed",
    }
}

/// Renders a human-oriented overview of the project, including component states,
/// compact document summaries, task progress, and next tasks.
pub fn render_overview(inspection: &ProjectInspection) -> String {
    let mut output = String::new();
    output.push_str("╭── Project Status ───────────────────────────────────────────────\n");
    output.push_str(&format!(
        "│  Project:  {} ({})\n",
        inspection.project_dir.display(),
        inspection.state.name()
    ));

    let mut total_tasks = 0;
    let mut total_completed = 0;
    let mut total_in_progress = 0;
    let mut total_pending = 0;
    let mut total_blocked = 0;

    struct CompSummary {
        path: String,
        state: &'static str,
        docs_summary: String,
        tasks_summary: Option<String>,
        next_task: Option<(String, String)>,
        guidance: Option<String>,
    }

    let mut comp_summaries = Vec::new();

    for component in &inspection.components {
        let comp_path_str = component.path.to_string_lossy().into_owned();
        let state_name = component.state.name();

        let total_artifacts = component.artifacts.len();
        let valid_artifacts = component
            .artifacts
            .iter()
            .filter(|a| a.state.name() == "valid")
            .count();

        let docs_summary = if total_artifacts > 0 && valid_artifacts == total_artifacts {
            format!("all valid ({valid_artifacts}/{total_artifacts})")
        } else {
            let invalid_or_missing: Vec<String> = component
                .artifacts
                .iter()
                .filter(|a| a.state.name() != "valid")
                .map(|a| format!("{}: {}", a.path, a.state.name()))
                .collect();
            if invalid_or_missing.is_empty() {
                "none".to_owned()
            } else {
                format!(
                    "{valid_artifacts}/{total_artifacts} valid (issues: {})",
                    invalid_or_missing.join(", ")
                )
            }
        };

        let component_dir = match &inspection.component_root {
            Some(root) => {
                if root == Path::new(".") {
                    inspection.project_dir.join(&component.path)
                } else {
                    inspection.project_dir.join(root).join(&component.path)
                }
            }
            None => inspection.project_dir.join(&component.path),
        };

        let (tasks_summary, next_task) =
            if let Ok(content) = fs::read_to_string(component_dir.join("TODOS.yaml")) {
                if let Ok(queue) = crate::task_queue::parse(&content) {
                    let comp_total = queue.tasks.len();
                    let comp_completed = queue
                        .tasks
                        .iter()
                        .filter(|t| t.status == crate::task_queue::TaskStatus::Completed)
                        .count();
                    let comp_in_progress = queue
                        .tasks
                        .iter()
                        .filter(|t| t.status == crate::task_queue::TaskStatus::InProgress)
                        .count();
                    let comp_pending = queue
                        .tasks
                        .iter()
                        .filter(|t| t.status == crate::task_queue::TaskStatus::Pending)
                        .count();
                    let comp_blocked = queue
                        .tasks
                        .iter()
                        .filter(|t| t.status == crate::task_queue::TaskStatus::Blocked)
                        .count();

                    total_tasks += comp_total;
                    total_completed += comp_completed;
                    total_in_progress += comp_in_progress;
                    total_pending += comp_pending;
                    total_blocked += comp_blocked;

                    let pct = (comp_completed * 100)
                        .checked_div(comp_total)
                        .unwrap_or(100);
                    let mut detail_parts = Vec::new();
                    if comp_in_progress > 0 {
                        detail_parts.push(format!("{comp_in_progress} in-progress"));
                    }
                    if comp_pending > 0 {
                        detail_parts.push(format!("{comp_pending} pending"));
                    }
                    if comp_blocked > 0 {
                        detail_parts.push(format!("{comp_blocked} blocked"));
                    }

                    let summary = if detail_parts.is_empty() {
                        format!("{comp_completed}/{comp_total} completed ({pct}%)")
                    } else {
                        format!(
                            "{comp_completed}/{comp_total} completed ({pct}%) [{}]",
                            detail_parts.join(", ")
                        )
                    };

                    let next = crate::task_queue::next_ready_task_id(&queue.tasks)
                        .and_then(|id| queue.tasks.iter().find(|t| t.id == id))
                        .map(|t| (t.id.clone(), t.title.clone()));

                    (Some(summary), next)
                } else {
                    (None, None)
                }
            } else {
                (None, None)
            };

        let guidance = match component.state {
            ComponentState::Stale => Some(format!(
                "Run 'kvist component accept {comp_path_str}' after review."
            )),
            ComponentState::Blocked => Some(format!(
                "Resolve blocked tasks in {comp_path_str}/TODOS.yaml."
            )),
            ComponentState::Invalid => Some(format!(
                "Run 'kvist component validate {comp_path_str}' to inspect invalid artifacts."
            )),
            ComponentState::Missing => Some(format!(
                "Run 'kvist component new {comp_path_str}' to create missing templates."
            )),
            ComponentState::UnsupportedVersion => Some(format!(
                "Upgrade or adapt the unsupported artifact versions in {comp_path_str}."
            )),
            ComponentState::Current => None,
        };

        comp_summaries.push(CompSummary {
            path: comp_path_str,
            state: state_name,
            docs_summary,
            tasks_summary,
            next_task,
            guidance,
        });
    }

    let overall_pct = (total_completed * 100)
        .checked_div(total_tasks)
        .unwrap_or(100);
    let mut overall_details = Vec::new();
    if total_in_progress > 0 {
        overall_details.push(format!("{total_in_progress} in-progress"));
    }
    if total_pending > 0 {
        overall_details.push(format!("{total_pending} pending"));
    }
    if total_blocked > 0 {
        overall_details.push(format!("{total_blocked} blocked"));
    }
    let details_suffix = if overall_details.is_empty() {
        String::new()
    } else {
        format!(" [{}]", overall_details.join(", "))
    };
    output.push_str(&format!(
        "│  Progress: {} components · {}/{} tasks completed ({}%){}\n",
        inspection.components.len(),
        total_completed,
        total_tasks,
        overall_pct,
        details_suffix
    ));

    for comp in comp_summaries {
        output.push_str("│\n");
        output.push_str(&format!("│  Component: {}\n", comp.path));
        output.push_str(&format!("│    State:     {}\n", comp.state));
        output.push_str(&format!("│    Documents: {}\n", comp.docs_summary));
        if let Some(tasks) = comp.tasks_summary {
            output.push_str(&format!("│    Tasks:     {}\n", tasks));
        }
        if let Some((next_id, next_title)) = comp.next_task {
            output.push_str(&format!(
                "│    Next task: {} (\"{}\")\n",
                next_id, next_title
            ));
        }
        if let Some(hint) = comp.guidance {
            output.push_str(&format!("│    Action:    {}\n", hint));
        }
    }

    output.push_str("╰─────────────────────────────────────────────────────────────────");
    output
}

